import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CltOnn6U.js";var i=JSON.parse(`{"title":"Overview","description":"Start here to configure relationships in WarpDrive; links each cardinality page from one-to-none through many-to-many plus the inverses, LinksMode, and polymorphism guides.","frontmatter":{"title":"Overview","description":"Start here to configure relationships in WarpDrive; links each cardinality page from one-to-none through many-to-many plus the inverses, LinksMode, and polymorphism guides."},"headers":[],"relativePath":"guides/the-manual/relational-data/index.md","filePath":"guides/the-manual/relational-data/index.md"}`),a={name:`guides/the-manual/relational-data/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="relationships-guide" tabindex="-1">Relationships Guide <a class="header-anchor" href="#relationships-guide" aria-label="Permalink to “Relationships Guide”">​</a></h1><h2 id="feature-overview" tabindex="-1">Feature Overview <a class="header-anchor" href="#feature-overview" aria-label="Permalink to “Feature Overview”">​</a></h2><ul><li><a href="./features/inverses">Inverses</a></li><li><a href="./../misc/links-mode">LinksMode</a></li><li><a href="./features/polymorphism">Polymorphism</a></li><li><a href="./../experiments/pagination">Pagination</a> (experimental): load a large collection page by page as its own request instead of through a relationship</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><ul><li><a href="./configuration/one-to-none">One To None</a> (1:0)</li><li><a href="./configuration/one-to-one">One To One</a> (1:1)</li><li><a href="./configuration/one-to-many">One To Many</a> (1:N)</li><li><a href="./configuration/many-to-none">Many To None</a> (N:0)</li><li><a href="./configuration/many-to-one">Many To One</a> (N:1)</li><li><a href="./configuration/many-to-many">Many To Many</a> (N:N)</li></ul><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to “Terminology”">​</a></h2><ul><li><strong>Inverse</strong>: the field on the related resource that points back to this one. If users have pets and pets have owners, the inverse of <code>user.pets</code> is <code>pet.owners</code>, and the inverse of <code>pet.owners</code> is <code>user.pets</code>. A to-none relationship has no inverse, which its schema declares as <code>inverse: null</code>. See <a href="./features/inverses">Inverses</a>.</li><li><strong>Self-referential</strong>: a relationship that points back at the same resource type, such as <code>person.parents</code> and <code>person.children</code>, which both belong to <code>person</code>.</li><li><strong>Reflexive</strong>: a self-referential relationship that is also its own inverse, such as <code>user.friends</code>.</li><li><strong>Circular</strong>: a self-referential or reflexive relationship whose value is the same record on both sides, such as a user who is their own best friend (<code>ego.bestFriend === ego</code>).</li><li><strong>Polymorphic</strong>: a relationship that more than one resource type can satisfy, such as <code>user.vehicles</code> holding <code>car</code>, <code>boat</code> and <code>airplane</code> records. See <a href="./features/polymorphism">Polymorphism</a>.</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};